-- Clinical knowledge standardization, step 1 of 3: additive schema.
-- See docs/clinical-knowledge/README.md for the template mapping and the plan.
--
-- What this does (nothing is deleted or rewritten):
--   1. Review lifecycle and template metadata on knowledge_base.
--      Every existing condition becomes 'clinical_review_pending': it is
--      published, but no clinician has formally reviewed it in PHYGO yet.
--   2. Translation status on condition_translations. Existing rows were
--      generated by OpenAI on first visit, so they become 'machine_generated'.
--   3. Traceable sources (clinical_sources) linked to the fields they support.
--   4. Rehabilitation protocols as their own resource (rehab_protocols), linked
--      to conditions, phases and existing exercises. The 74 phased protocols
--      that exist today (rehab_phases grouped by condition) are backfilled as
--      one protocol each, keeping rehab_phases.condition_id so the current app
--      keeps working unchanged.
--   5. A private staging table (clinical_content_drafts) for new or revised
--      content. Drafts never appear in the app: only promote_condition_draft()
--      copies an 'approved' draft into knowledge_base.
--
-- Safe to run more than once (IF NOT EXISTS / ON CONFLICT everywhere).
-- Rollback: sql/2026-10_clinical_knowledge_01_rollback.sql

begin;

-- 1. knowledge_base: lifecycle + template metadata -----------------------------

alter table knowledge_base
  add column if not exists review_status text,
  add column if not exists reviewed_by text,
  add column if not exists reviewed_at timestamptz,
  add column if not exists review_notes text,
  add column if not exists synonyms text[] not null default '{}',
  add column if not exists specialty text,
  add column if not exists body_region text,
  -- Template points 3 and 4, which had no column: overview / typical
  -- presentation / symptoms / functional limits, and history-taking and
  -- assessment considerations.
  add column if not exists clinical_presentation text,
  add column if not exists assessment_considerations text,
  -- Distinguishes "not applicable to this condition" from "missing": a field
  -- that is genuinely inapplicable is listed here as 'not_applicable'; an
  -- empty column with no entry here is simply missing content.
  add column if not exists field_status jsonb not null default '{}'::jsonb,
  -- Stable, human-readable key for idempotent imports (new records only).
  add column if not exists slug text,
  add column if not exists updated_at timestamptz;

update knowledge_base set review_status = 'clinical_review_pending' where review_status is null;
alter table knowledge_base alter column review_status set default 'clinical_review_pending';
alter table knowledge_base alter column review_status set not null;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'knowledge_base_review_status_check') then
    alter table knowledge_base add constraint knowledge_base_review_status_check
      check (review_status in ('draft', 'source_checked', 'clinical_review_pending', 'clinically_reviewed', 'approved'));
  end if;
end $$;

create unique index if not exists knowledge_base_slug_key on knowledge_base (slug) where slug is not null;

-- 2. condition_translations: translation status ---------------------------------

alter table condition_translations
  add column if not exists translation_status text not null default 'machine_generated',
  add column if not exists reviewed_by text,
  add column if not exists reviewed_at timestamptz;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'condition_translations_status_check') then
    alter table condition_translations add constraint condition_translations_status_check
      check (translation_status in ('machine_generated', 'human_reviewed'));
  end if;
end $$;

-- 3. Sources ---------------------------------------------------------------------

create table if not exists clinical_sources (
  id bigint generated by default as identity primary key,
  citation text not null,
  source_type text not null
    check (source_type in ('guideline', 'systematic_review', 'meta_analysis', 'rct', 'cohort', 'consensus', 'textbook', 'expert_opinion', 'other')),
  year int,
  doi text,
  pmid text,
  url text,
  -- Filled only when a person or the import validator has checked that the
  -- identifier resolves to this citation (never set by hand "on trust").
  verified_at timestamptz,
  verified_by text,
  verification_method text,
  created_at timestamptz not null default now()
);
create unique index if not exists clinical_sources_doi_key on clinical_sources (lower(doi)) where doi is not null;
create unique index if not exists clinical_sources_pmid_key on clinical_sources (pmid) where pmid is not null;

create table if not exists condition_sources (
  condition_id bigint not null references knowledge_base (id) on delete cascade,
  source_id bigint not null references clinical_sources (id) on delete restrict,
  -- Template field keys this source supports, e.g. {red_flags, clinical_tests}.
  supports text[] not null default '{}',
  evidence_note text,
  primary key (condition_id, source_id)
);

-- 4. Rehabilitation protocols ------------------------------------------------------

create table if not exists rehab_protocols (
  id bigint generated by default as identity primary key,
  slug text not null unique,
  title text not null,
  population text,
  inclusion_criteria text,
  exclusion_criteria text,
  baseline_assessment text,
  precautions text,
  outcome_measures text,
  reassessment_points text,
  return_criteria text,
  translations jsonb not null default '{}'::jsonb,
  field_status jsonb not null default '{}'::jsonb,
  review_status text not null default 'clinical_review_pending'
    check (review_status in ('draft', 'source_checked', 'clinical_review_pending', 'clinically_reviewed', 'approved')),
  reviewed_by text,
  reviewed_at timestamptz,
  review_notes text,
  -- Set only for protocols backfilled from the legacy rehab_phases.condition_id grouping.
  legacy_condition_id bigint unique,
  created_at timestamptz not null default now(),
  updated_at timestamptz
);

create table if not exists rehab_protocol_conditions (
  protocol_id bigint not null references rehab_protocols (id) on delete cascade,
  condition_id bigint not null references knowledge_base (id) on delete cascade,
  is_primary boolean not null default false,
  primary key (protocol_id, condition_id)
);
create index if not exists rehab_protocol_conditions_condition_idx on rehab_protocol_conditions (condition_id);

create table if not exists protocol_sources (
  protocol_id bigint not null references rehab_protocols (id) on delete cascade,
  source_id bigint not null references clinical_sources (id) on delete restrict,
  supports text[] not null default '{}',
  evidence_note text,
  primary key (protocol_id, source_id)
);

alter table rehab_phases
  add column if not exists protocol_id bigint references rehab_protocols (id) on delete restrict,
  add column if not exists regression_criteria text,
  add column if not exists reassessment text;
create index if not exists rehab_phases_protocol_id_idx on rehab_phases (protocol_id);
create index if not exists rehab_phases_condition_id_idx on rehab_phases (condition_id);

-- Phase exercises reuse the existing exercise library instead of free text.
create table if not exists rehab_phase_exercises (
  phase_id bigint not null references rehab_phases (id) on delete cascade,
  exercise_id uuid not null references exercises (id) on delete restrict,
  dosage text,
  progression_note text,
  regression_note text,
  sort_order int not null default 0,
  primary key (phase_id, exercise_id)
);

-- One protocol per existing condition that has phases. Re-runnable: it only
-- creates what is missing, and only links phases that have no protocol yet.
create or replace function backfill_legacy_protocols() returns void
language sql as $$
  insert into rehab_protocols (slug, title, legacy_condition_id, review_status)
  select 'condition-' || k.id, k.condition_name, k.id, 'clinical_review_pending'
  from knowledge_base k
  where exists (select 1 from rehab_phases r where r.condition_id = k.id)
  on conflict do nothing;

  insert into rehab_protocol_conditions (protocol_id, condition_id, is_primary)
  select p.id, p.legacy_condition_id, true
  from rehab_protocols p
  join knowledge_base k on k.id = p.legacy_condition_id
  on conflict do nothing;

  update rehab_phases r
  set protocol_id = p.id
  from rehab_protocols p
  where p.legacy_condition_id = r.condition_id and r.protocol_id is null;
$$;

select backfill_legacy_protocols();

-- 5. Private staging for new content -------------------------------------------------

create table if not exists clinical_content_drafts (
  id bigint generated by default as identity primary key,
  kind text not null check (kind in ('condition', 'protocol')),
  slug text not null,
  payload jsonb not null,
  review_status text not null default 'draft'
    check (review_status in ('draft', 'source_checked', 'clinical_review_pending', 'clinically_reviewed', 'approved')),
  validation_report jsonb,
  reviewed_by text,
  reviewed_at timestamptz,
  -- knowledge_base.id / rehab_protocols.id once promoted.
  target_id bigint,
  created_at timestamptz not null default now(),
  updated_at timestamptz,
  unique (kind, slug)
);

-- Copies one approved condition draft into knowledge_base. Refuses anything
-- that is not 'approved' and never creates a second row for the same slug.
create or replace function promote_condition_draft(p_slug text) returns bigint
language plpgsql as $$
declare
  d clinical_content_drafts%rowtype;
  new_id bigint;
begin
  select * into d from clinical_content_drafts where kind = 'condition' and slug = p_slug for update;
  if not found then
    raise exception 'No condition draft with slug %', p_slug;
  end if;
  if d.review_status <> 'approved' then
    raise exception 'Draft % is %, only approved drafts can be published', p_slug, d.review_status;
  end if;
  if d.target_id is not null then
    return d.target_id;
  end if;
  select id into new_id from knowledge_base where slug = p_slug;
  if new_id is null then
    insert into knowledge_base (
      condition_name, condition_keywords, synonyms, specialty, body_region,
      clinical_presentation, assessment_considerations,
      goals, clinical_tests, red_flags, contraindications, typical_exercises,
      progression_criteria, return_to_activity_criteria, outcome_measures,
      pathophysiology, etiology_risk_factors, differential_diagnosis,
      icd10_code, evidence_level, source, source_date,
      field_status, slug, review_status, reviewed_by, reviewed_at
    )
    select
      p->>'condition_name',
      array_to_string(array(select jsonb_array_elements_text(coalesce(p->'synonyms', '[]'::jsonb))), ','),
      array(select jsonb_array_elements_text(coalesce(p->'synonyms', '[]'::jsonb))),
      p->>'specialty', p->>'body_region',
      p->>'clinical_presentation', p->>'assessment_considerations',
      p->>'goals', p->>'clinical_tests', p->>'red_flags', p->>'contraindications', p->>'typical_exercises',
      p->>'progression_criteria', p->>'return_to_activity_criteria', p->>'outcome_measures',
      p->>'pathophysiology', p->>'etiology_risk_factors', p->>'differential_diagnosis',
      p->>'icd10_code', p->>'evidence_level',
      array_to_string(array(select s->>'citation' from jsonb_array_elements(coalesce(p->'sources', '[]'::jsonb)) s), '; '),
      p->>'source_date',
      coalesce(p->'field_status', '{}'::jsonb), p_slug, 'approved', d.reviewed_by, d.reviewed_at
    from (select d.payload as p) x
    returning id into new_id;
  end if;
  update clinical_content_drafts set target_id = new_id, updated_at = now() where id = d.id;
  return new_id;
end $$;

-- 6. Row-level security ----------------------------------------------------------------
-- Protocols, links and sources are public reference content, like
-- knowledge_base and rehab_phases today. Writes go through the service role.
-- Drafts have no policy at all: only the service role can read or write them.

alter table clinical_sources enable row level security;
alter table condition_sources enable row level security;
alter table rehab_protocols enable row level security;
alter table rehab_protocol_conditions enable row level security;
alter table protocol_sources enable row level security;
alter table rehab_phase_exercises enable row level security;
alter table clinical_content_drafts enable row level security;

drop policy if exists "Public read access" on clinical_sources;
create policy "Public read access" on clinical_sources for select using (true);
drop policy if exists "Public read access" on condition_sources;
create policy "Public read access" on condition_sources for select using (true);
drop policy if exists "Public read access" on rehab_protocols;
create policy "Public read access" on rehab_protocols for select using (true);
drop policy if exists "Public read access" on rehab_protocol_conditions;
create policy "Public read access" on rehab_protocol_conditions for select using (true);
drop policy if exists "Public read access" on protocol_sources;
create policy "Public read access" on protocol_sources for select using (true);
drop policy if exists "Public read access" on rehab_phase_exercises;
create policy "Public read access" on rehab_phase_exercises for select using (true);

-- Supabase grants EXECUTE to anon/authenticated by default; these two
-- functions are for the service role only.
revoke all on function promote_condition_draft(text) from public, anon, authenticated;
revoke all on function backfill_legacy_protocols() from public, anon, authenticated;

commit;
